function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fill("#e08a72", 100); // orange
  brush.fillBleed(0.6);      // strong orange

  // Sky
  brush.fill("#e6f9ff", 20); // soft blue
  brush.fillTexture(1.0, true); // texture

  // Hills, medium green
  brush.fill("#41714d", 100);
  brush.fillTexture(0.5, false); // light leather
  brush.beginShape();
  brush.vertex(0, 0);        // top left hill
  brush.vertex(200, 40);    // top middle hill
  brush.vertex(400, 0);     // top right hill
  brush.endShape(true);

  // Hills, thin green (lower ground)
  brush.fill("#557f55", 100);
  brush.fillTexture(0.2, false);
  brush.beginShape();
  brush.vertex(0, 180);     // low left hill
  brush.vertex(200, 200);  // low middle hill
  brush.vertex(400, 180);  // low right hill
  brush.endShape(true);

  // Ground
  brush.fill("#1d3627", 100);
  brush.fillTexture(0.0, false);
  brush.beginShape();
  brush.vertex(0, 250);     // bottom left hill
  brush.vertex(200, 320);   // bottom middle hill
  brush.vertex(400, 250);   // bottom right hill
  brush.endShape(true);

  // Gradient along the bottom
  brush.fillTexture(0.5, false);
  brush.beginShape();
  brush.vertex(0, 300);     // left hill edge
  brush.vertex(200, 380);   // middle hill edge
  brush.vertex(400, 300);   // right hill edge
  brush.endShape(true);

  // Scapegoat tree (points)
  brush.fillTexture(0.8, true);
  brush.beginShape();
  brush.vertex(0, 350);
  brush.vertex(100, 300);   // left
  brush.vertex(200, 250);   // middle
  brush.vertex(300, 300);   // right
  brush.endShape(true);

  // Silhouette
  brush.fill("#7a3a1a", 255);
  brush.fillTexture

