  brush.fill("#8a8ae6", 50); // Western sun
  brush.fillTexture(0.7, "textured");
  brush.fillTexture(0.1, "circle");
  brush.fill("#f57b00", 100); // Ground
  brush.fillTexture(0.6, "gradient");
  brush.fill("#8a8ae6", 100); // Hills

