  brush.beginShape();
  brush.vertex(200, 100);  // Top left hill
  brush.vertex(280, 300);  // Top right hill
  brush.vertex(320, 280);  // Bottom left hill
  brush.vertex(200, 320);  // Bottom right hill
  brush.endShape(true);

  // Sun
  brush.beginShape();
  brush.vertex(140, 140);  // Sun top
  brush.vertex(180, 180);  // Sun top right
  brush.vertex(220, 140);  // Sun bottom right
  brush.vertex(180, 100);  // Sun bottom
  brush.endShape(true);

  // Forest
  brush.beginShape();
  brush.vertex(80, 250);  // Oak tree top
  brush.vertex(120, 220);  // Oak tree top right
  brush.vertex(160, 270);  // Oak tree top left
  brush.vertex(120, 290);  // Oak tree bottom right
