  brush.endShape(true);

  brush.beginShape();
  brush.vertex(160, 350);  // Oak tree bottom left
  brush.vertex(120, 390);  // Oak tree bottom right
  brush.vertex(180, 390);  // Oak tree bottom right
  brush.vertex(200, 350);  // Oak tree bottom right
  brush.endShape(true);
}
