function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();
  brush.fill("#f4efe4", 1); // sky
  brush.fill("#82a38b", 1); // sun
  brush.fill("#4f7440", 1); // flame
  brush.fill("#f8f0e5", 1); // ground
  brush.fill("#613a18", 1); // hills
  brush.fill("#5e5f5f", 1); // hills text
  brush.fillBleed(0.15); // vertical streaks

  // horizon
  brush.fill("#d6d6d6", 1);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(0, 380);
  brush.vertex(400, 380);
  brush.vertex(400, 0);
  brush.endShape(true);

  // hills, waving
  brush.beginShape();
  brush.vertex(0, 150);
  brush.vertex(400, 100);
  brush.vertex(100, 200);
  brush.vertex(300, 180);
  brush.endShape(true);

  // clouds, brush texture with border
  brush.fillTexture(0.7, 0.7);
  brush.fill("#613a18", 0.8);
  brush.drawBrush(100, 100);

  // flame to add some width and color contrast
  brush.fillTexture(0.7, 0.3);
  brush.beginShape();
  brush.vertex(0, 260);
  brush.vertex(0, 320);
  brush.vertex(400, 270);
  brush.vertex(400, 330);
  brush.endShape(true);

  // central skyline (you can vary the height for greens)
  brush.fill("#3b5f37", 1);
  brush.beginShape();
  brush.vertex(0, 240);
  brush.vertex(0, 200);
  brush.vertex(400, 190);
  brush.vertex(400, 220);
  brush.endShape(true);

  brush.fill("#8f6d29", 1); // horizon border
  brush.drawBrush(100, 200);
}
