function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();
  brush.fill("#a4c050", 200); // Sky
  brush.fillBleed(0.25); // Opaque on the edge

  // Green hills
  brush.fill("#21762a", 200); // Green
  brush.beginShape();
  brush.vertex(0, 0); // Top left hill
  brush.vertex(200, 100); // Top middle hill
  brush.vertex(400, 0); // Top right hill
  brush.endShape(true);

  // Smoother green hills with added curvature
  brush.fill("#21762a", 160);
  brush.beginShape();
  brush.vertex(100, 100); // Bottom left hill
  brush.vertex(300, 150); // Bottom middle hill
  brush.vertex(300, 250); // Bottom right hill
  brush.endShape(true);

  // Gradient across the hills
  for (let x = 0; x <= 400; x += 20) {
    brush.fillGradient(x / 200, 0.4, 0.4, 0.7, 1, 1, "linear-gradient(#b5e09f, #51b883)"); // Sunset shade
    brush.vertex(x, 0); // Top of hill
  }

  // Sun
  brush.fill("#f8b563", 100); // Yellow
  brush.beginShape();
  brush.vertex(200, 130); // Top of sun
  brush.vertex(180, 200); // Right of sun
  brush.vertex(220, 200); // Left of sun
  brush.endShape(true);
  brush.fill("#f0ad4e", 200); // Red
  brush.circle(200, 215, 45); // Big red light

  // Ground
